Change request 18: Count a commit as checked only if its check is less than a day old.
Seeded problem (the answer key): {"problem": "breakage", "type": "breaks-past-behavior", "against": "commits approved on checks older than a day"}
Elements it is bound to: ["authoring/invariant:approved-commits-passed-their-checks", "authoring/precondition:approve_commit.checks-pass", "authoring/action:record_check", "authoring/property:Commit.checks_passed"]; note: a time limit on what counts as checked

=== B ===
The edit: --- a/authoring.domain.yaml
+++ b/authoring.domain.yaml
@@ -176,10 +176,13 @@
       release_name:
         type: string
         optional: true
-    source:
-      kind: interview
-      ref: interview:domains/authoring/interview.jsonl#L53
-    status: confirmed
+      checked_at:
+        type: datetime
+        optional: true
+    source:
+      kind: interview
+      ref: interview:domains/authoring/interview.jsonl#L56
+    status: proposed
   Draft:
     description: 'The working copy of a domain''s declaration on a branch: what a
       commit snapshots.'
@@ -523,11 +526,11 @@
     - set:
         target.checks_passed: params.passed
         target.failing: params.summary
-    source:
-      kind: interview
-      ref: interview:domains/authoring/interview.jsonl#L5
-      quote: 9번은 추천대로 하면 될 것 같고 10번도 추천대로 하면 될 것 같아. 일단 A로 가되 나중에 추가할 수 있는 거지?
-    status: confirmed
+        target.checked_at: now()
+    source:
+      kind: interview
+      ref: interview:domains/authoring/interview.jsonl#L56
+    status: proposed
     preconditions:
     - id: settled
       check: target.approved != true
@@ -535,7 +538,7 @@
       source:
         kind: record
         ref: records:docs/commits.md#L128-L142
-      status: confirmed
+      status: proposed
   approve_commit:
     description: 'Approve a commit: merge it into main and tag it. Only a person approves;
       the owner, or the deputy the owner has named while away.'
@@ -552,20 +555,18 @@
         commit: target.id
         approver: actor.id
       reply: record_approval
-    source:
-      kind: interview
-      ref: interview:domains/authoring/interview.jsonl#L49
-    status: confirmed
+    source: &id001
+      kind: interview
+      ref: interview:domains/authoring/interview.jsonl#L56
+    status: proposed
     preconditions:
     - id: checks-pass
-      check: target.checks_passed == true or target.wording_only == true
-      reason: Run the change check, and approve only a commit that passes it, unless
-        only its wording changed.
-      source:
-        kind: interview
-        ref: interview:domains/authoring/interview.jsonl#L6
-        quote: 전부 다 추천한 거 동의.
-      status: confirmed
+      check: (target.checks_passed == true and exists(target.checked_at) and now()
+        - target.checked_at < duration('24h')) or target.wording_only == true
+      reason: Run the change check, and approve only a commit that passed it within
+        the last day, unless only its wording changed.
+      source: *id001
+      status: proposed
     - id: not-approved
       check: target.approved != true
       reason: Already approved; approve a newer commit.

